export interface Schema {
  readonly kind: 'Schema';
  readonly types: readonly string[];
}
export interface GqlRequest {
  path: string;
}
export interface GqlReply {
  send(body: unknown): void;
}
export type RequestHandler = (request: GqlRequest, reply: GqlReply, next: () => void) => void;
/** Serves `schema` over HTTP at `endpoint`, or at its own default endpoint when none is given. */
export declare function createGqlServer(options: { schema: Schema; endpoint?: string }): RequestHandler;
